def transform(grid):
    from collections import Counter
    bg_count = Counter()
    for row in grid:
        bg_count.update(row)
    bg = bg_count.most_common(1)[0][0]

    h, w = len(grid), len(grid[0])

    if w >= 27:
        k, n_rows = 3, 3
    elif w >= 23:
        k, n_rows = 4, 2
    else:
        k, n_rows = 4, 2

    output = []
    consecutive = 0

    for r in range(min(h, 10)):
        row_segment = grid[r][:k]
        has_fg = any(val != bg for val in row_segment)

        if has_fg:
            if consecutive < n_rows:
                output.append(row_segment)
            else:
                return output
            consecutive += 1
        else:
            consecutive = 0

